// Planted sleeps and the lookalikes that must stay legal, one row per shape. A row is [row, code, rule that must report it,
// messageId or message fragment]. The row number is the bypass class (1 to 14) plus a letter; `:name` marks a variant.
// A shape is either a row here or a line in the Known gaps comment in eslint/no-sleep.js, never both.
export const PROMISE = 'local/no-sleep-promise';
export const ALIAS = 'local/no-timer-alias';
export const SYNTAX = 'no-restricted-syntax';
export const API = 'local/no-sleep-api';

export type BannedCase = [row: string, code: string, rule: string, id: string];

