// Shapes that still get through. Each is a line in the Known gaps comment in eslint/no-sleep.js: closing one moves it to bannedCases.
// bullet is the 0-based position of the shape's line in the Known gaps comment in eslint/no-sleep.js; the test checks every line has a case.
export const gapCases: Array<[name: string, code: string, bullet: number]> = [
  ['a resolve reaching a timer through an imported helper', "import { waitFn } from './helpers'; await new Promise((r) => waitFn(r));", 0],
  ['a resolve reaching a timer through an object-literal method', 'const h = { after: (f: () => void) => setTimeout(f, 50) }; await new Promise<void>((r) => h.after(r));', 6],
  ['a resolve inside an object handed to a helper', 'const after = ({ f }: { f: () => void }) => setTimeout(f, 50); await new Promise<void>((r) => after({ f: r }));', 6],
  ['a resolve reached through for-of over an array literal', 'const d = Promise.withResolvers<void>(); for (const f of [d.resolve]) setTimeout(f, 50); await d.promise;', 6],
  ['the clock read through a function imported from another module', "import { now } from './clock'; const end = now() + 500; while (now() < end) {}", 7],
  ['the host reached through itself, globalThis.globalThis', 'await new Promise((r) => globalThis.globalThis.setTimeout(r, 50));', 8],
  ['the host reached through itself, window.self', 'await new Promise((r) => window.self.setTimeout(r, 50));', 8],
  ['a script assembled at runtime', "await page.evaluate('set' + 'Timeout(() => 0, 5)');", 1],
  ['a timer key assembled at runtime', "const k = 'set' + 'Timeout'; await new Promise((r) => (globalThis as any)[k](r, 50));", 1],
  ['a timer spun in a loop that never reads the clock', 'for (let i = 0; i < 1e9; i++) {}', 7],
  ['a Promise subclass imported from another module', "import { Base } from './base'; await new (class extends Base {})((r) => setTimeout(r, 5));", 15],
  ['the host handed to a function as an argument', 'function f(g: typeof globalThis) { return new Promise((r) => g.setTimeout(r, 50)); } await f(globalThis);', 3],
  ['a timer key computed by a call', "const k = pick(); await new Promise((r) => (globalThis as any)[k](r, 50));", 1],
  ['createRequire of timers', "const t = createRequire(import.meta.url)('timers'); void t;", 4],
  ['module.require of timers', "const t = module.require('timers'); void t;", 4],
  ['a withResolvers bag returned from a local function', 'const mk = () => Promise.withResolvers<void>(); const d = mk(); setTimeout(() => d.resolve(), 50); await d.promise;', 5],
  ['a script handed to a local function as an argument', "async function run(s: string) { await page.evaluate(s); } await run('setTimeout(() => 0, 5)');", 2],
  ['a module name assembled at runtime', "const m = 'time' + 'rs'; const t = await import(m); void t;", 1],
  ['a timer built in another module', "import { later } from './timers'; await later(50);", 0],
  ['the clock read by call', 'const end = Date.now() + 500; while (Date.now.call(Date) < end) {}', 9],
  ['the clock read by Reflect.apply', 'const end = Date.now() + 500; while (Reflect.apply(Date.now, Date, []) < end) {}', 9],
  ['the clock held in an object', 'const end = Date.now() + 500; const c = { now: Date.now }; while (c.now() < end) {}', 9],
  ['a local clock function picked by another name', 'const end = Date.now() + 500; const f = () => Date.now(); const g = opts.g ?? f; while (g() < end) {}', 9],
  ['a resolve wrapped in an arrow and stored before a timing helper', 'function after(f: () => void) { setTimeout(f, 50); } await new Promise<void>((r) => { const g = () => r(); after(g); });', 10],
  ['a resolve bound and stored before a timing helper', 'function after(f: () => void) { setTimeout(f, 50); } await new Promise<void>((r) => { const g = r.bind(null); after(g); });', 10],
  ['a timer started by AbortSignal.timeout', `await new Promise((r) => AbortSignal.timeout(50).addEventListener('abort', r));`, 11],
  ['setImmediate used as a flush', 'await new Promise((r) => setImmediate(r));', 11],
  ['the timer read by Reflect.get', `const f = Reflect.get(globalThis, 'setTimeout'); await new Promise((r) => f(r, 50));`, 12],
  ['the host spread into an object', 'const g = { ...globalThis }; await new Promise((r) => g.setTimeout(r, 50));', 12],
  ['a resolve picked out of an array before a timing helper', 'function after(f: () => void) { setTimeout(f, 50); } await new Promise<void>((r) => after([r][0]));', 13],
  ['a resolve passed on by a wrapper to another call', 'function after(f: () => void) { setTimeout(f, 50); } await new Promise<void>((r) => after(() => Promise.resolve().then(r)));', 13],
  ['a class holding a bag copied to another name', 'class Q { static d = Promise.withResolvers<void>(); } const Z = Q; setTimeout(Z.d.resolve, 5);', 14],
  ['a bag read off a class by destructuring', 'class Q { static d = Promise.withResolvers<void>(); } const { d } = Q; setTimeout(d.resolve, 5);', 14],
  ['a bag read off a class instance', 'class Q { d = Promise.withResolvers<void>(); } const q = new Q(); setTimeout(q.d.resolve, 5);', 14],
  ['a bag held by an object that is copied', 'const Q = { d: Promise.withResolvers<void>() }; const Z = Q; setTimeout(Z.d.resolve, 5);', 14],
];

// False positives the rule accepts, named in the same comment.
export const acceptedFalsePositives: Array<[name: string, code: string, rule: string]> = [
  ['a variable named sleep', 'const sleep = 50; export { sleep };', SYNTAX],
  ['a deadline guard that calls reject through an object literal', "await new Promise((r, rej) => { const o = { rej }; setTimeout(() => o.rej(new Error('late')), 50); });", PROMISE],
  ['a counted loop with a clock guard that breaks', 'const end = Date.now() + 500; for (let i = 0; i < 10; i++) { if (Date.now() > end) break; }', API],
  ['a deadline guard whose timer callback redeclares the resolve name', 'await new Promise((r, rej) => { setTimeout(() => { const r = 1; void r; rej(new Error("late")); }, 50); });', PROMISE],
  ['a local object named scheduler with a wait method', 'const scheduler = { wait: (n: number) => n }; scheduler.wait(50);', API],
  ['a local object named Atomics with a wait method', 'const Atomics = { wait: (n: number) => n }; Atomics.wait(1);', API],
  ['a Promise executor that is queueMicrotask', 'await new Promise(queueMicrotask);', PROMISE],
  ['a Promise executor that is process.nextTick', 'await new Promise(process.nextTick);', PROMISE],
  ['a Promise executor that is setImmediate', 'await new Promise(setImmediate);', PROMISE],
  ['a poll loop that sleeps between checks under one deadline', 'declare function check(): Promise<boolean>; let ok = false; const start = Date.now(); while (!ok && Date.now() - start < 1000) { ok = await check(); await new Promise((r) => setTimeout(r, 50)); }', PROMISE],
  ['a timer a fake clock advances at once', `import { vi } from 'vitest'; vi.useFakeTimers(); await new Promise<void>((r) => { setTimeout(r, 1000); vi.advanceTimersByTime(1000); });`, PROMISE],
];
